CATALOGUE = START + r'''
<section class="market-intro" aria-labelledby="page-title"><div><p class="eyebrow">IBROWS AGRICULTURE</p><h1 id="page-title">Fresh produce marketplace</h1><p>Browse available farm produce and enquire directly through IBROWS. No registration required.</p></div><a class="button secondary" href="/agriculture/marketplace/sell">Sell your produce</a></section>
<form class="search-panel" method="get" aria-label="Search farm produce"><div class="field"><label for="commodity">Produce</label><input id="commodity" name="commodity" placeholder="e.g. maize, soya, groundnuts" value="{{ commodity }}"></div><div class="field"><label for="location">Location</label><input id="location" name="location" placeholder="District or area" value="{{ location }}"></div><button type="submit">Find produce</button></form>
<div class="results-header"><div><h2>Available produce</h2><p>{{ rows|length }} listing{{ '' if rows|length == 1 else 's' }}{% if commodity or location %} matching your search{% endif %}</p></div>{% if commodity or location %}<a href="{{ url_for('agro_marketplace.catalogue') }}">Clear filters</a>{% endif %}</div>
<div class="produce-list">{% for p in rows %}{% set stock = p[3]|agro_stock(p[4]) %}<article class="produce-card"><div class="card-top"><p class="eyebrow">FARM PRODUCE</p><span class="badge available">Available</span></div><div class="card-body"><div>{% if p[9] %}<img src="{{ url_for('agro_marketplace.approved_produce_photo', photo_id=p[9]) }}" alt="Photo of {{p[1]}}" loading="lazy" style="display:block;width:100%;height:170px;object-fit:cover;border-radius:10px;margin-bottom:12px">{% endif %}<h2 class="produce-title">{{p[1]}}</h2>{% if p[2] and (p[2]|lower) not in (p[1]|lower) %}<p class="grade">Grade / variety: {{p[2]}}</p>{% endif %}<p class="stock">{{stock.amount}} {{stock.unit}} available</p>{% if stock.pack %}<p class="pack">{{stock.pack}}</p>{% endif %}</div><div><p class="detail-label">Location</p><p class="location">{{p[7]}}</p>{% if p[8] %}<p class="description">{{p[8]}}</p>{% endif %}</div><div class="purchase"><p class="price">{% if p[5] is not none %}MK {{p[5]|agro_money}}{% else %}On enquiry{% endif %}</p><p class="price-unit">{% if p[5] is not none %}per {{p[6] or p[4]}}{% else %}Ask IBROWS for the current price{% endif %}</p><a class="button" href="{{ url_for('agro_marketplace.buyer_enquiry', listing_id=p[0]) }}">Enquire through IBROWS</a><p class="small-note">Stock and final price confirmed by our team.</p></div></div></article>{% else %}<section class="empty"><h3>{% if commodity or location %}No produce matches your search{% else %}More produce is on the way{% endif %}</h3><p>{% if commodity or location %}Try another produce name or a nearby location.{% else %}Available listings appear here after review by IBROWS.{% endif %}</p><a class="button secondary" href="{% if commodity or location %}/agriculture/marketplace{% else %}/agriculture?sell=1{% endif %}">{% if commodity or location %}View all produce{% else %}Contact IBROWS about produce{% endif %}</a></section>{% endfor %}</div>

''' + END

ENQUIRY = START + r'''
<div class="page-heading"><a class="back-link" href="/agriculture/marketplace">← Back to available produce</a><p class="eyebrow">BUYER ENQUIRY</p><h1>Enquire about {{listing[1]}}{% if listing[2] %} · {{listing[2]}}{% endif %}</h1><p class="intro">Let IBROWS know what you need. Our team will contact you to discuss availability and the next steps.</p></div>
<p class="notice">{% if listing[3] is not none %}MK {{listing[3]|agro_money}} per {{listing[4]}} · {% endif %}Current stock and final price confirmed by IBROWS.</p><div class="form-layout"><section class="panel"><h2>Your contact details</h2>{% if error %}<p class="error" role="alert">{{error}}</p>{% endif %}<form method="post"><input type="hidden" name="csrf_token" value="{{csrf}}"><input class="honeypot" name="fax_number" tabindex="-1" autocomplete="off" aria-hidden="true"><div class="form-grid"><div class="field"><label for="buyer-name">Full name <span aria-hidden="true">*</span></label><input id="buyer-name" name="name" autocomplete="name" maxlength="180" required value="{{request.form.get('name','')}}"></div><div class="field"><label for="buyer-phone">Phone number <span aria-hidden="true">*</span></label><input id="buyer-phone" name="phone" type="tel" autocomplete="tel" placeholder="e.g. +265 888 123 456" maxlength="80" required value="{{request.form.get('phone','')}}"></div><div class="field full"><label for="buyer-message">What would you like to arrange?</label><textarea id="buyer-message" name="message" maxlength="2000" placeholder="Tell us the quantity you need, your area and any collection or delivery preferences.">{{request.form.get('message','')}}</textarea></div><label class="check full"><input type="checkbox" name="consent" value="1" required{% if request.form.get('consent')=='1' %} checked{% endif %}><span>I consent to IBROWS contacting me about this enquiry. My contact details will not be published.</span></label></div><div class="form-actions"><button type="submit">Send enquiry to IBROWS</button><a href="/agriculture/marketplace">Back to produce</a></div></form></section><aside class="panel side-panel"><h2>Handled by IBROWS</h2><div><h3>Availability first</h3><p>We confirm the available stock and current price before any transaction is agreed.</p></div><div><h3>Your details stay private</h3><p>This enquiry goes to the IBROWS team. Your phone number does not appear on the marketplace.</p></div></aside></div>
''' + END

SUCCESS = START + r'''
<section class="panel confirmation"><span class="badge available">Sent to IBROWS</span><h1>Enquiry received</h1><p class="intro">Thank you. IBROWS will contact you to discuss the produce and confirm the arrangements.</p><div class="reference">Your enquiry reference<strong>AG-BUY-{{id}}</strong></div><p class="small-note">This is an enquiry. Availability, final price and collection or delivery details still need to be confirmed.</p><div class="form-actions"><a class="button" href="/agriculture/marketplace">Back to available produce</a></div></section>
''' + END

MODERATION = START + r'''
<div class="page-heading"><a class="back-link" href="/admin/service-requests">← Buyer enquiries and service requests</a><p class="eyebrow">IBROWS ADMINISTRATION</p><h1>Manage produce listings</h1><p class="intro">Keep available quantities and listing status up to date. Approved listings with remaining stock appear on the marketplace.</p></div>
<p class="notice">Before approving, confirm seller permission, current stock and price. Set remaining stock to 0 to mark a listing sold out.</p>
<div class="results-header"><h2>{{rows|length}} listing{{ '' if rows|length==1 else 's' }}</h2><a href="/agriculture/marketplace">View public marketplace</a></div>
<div class="produce-list">{% for p in rows %}{% set stock = p[2]|agro_stock(p[3]) %}<section class="produce-card admin-card"><div class="card-top"><p class="eyebrow">LISTING #{{p[0]}}</p><span class="badge{% if p[5]!='APPROVED' %} neutral{% endif %}">{{p[5]|replace('_',' ')|title}}</span></div><div class="card-body"><div>{% if p[10] %}<img src="{{ url_for('agro_marketplace.admin_produce_photo', photo_id=p[10]) }}" alt="Seller's submitted photo of {{p[1]}}" loading="lazy" style="display:block;width:100%;max-width:340px;height:170px;object-fit:cover;border-radius:10px;margin-bottom:12px">{% endif %}<h2 class="produce-title">{{p[1]}}</h2><p class="grade">{{p[7] or "Standard"}}</p><p class="stock">{{stock.amount}} {{stock.unit}} remaining</p>{% if stock.pack %}<p class="pack">{{stock.pack}}</p>{% endif %}<p class="description">{{p[4]}}</p></div><div><form class="admin-controls" method="post"><input type="hidden" name="csrf_token" value="{{csrf}}"><input type="hidden" name="listing_id" value="{{p[0]}}"><div class="field"><label for="stock-{{p[0]}}">Remaining stock ({{stock.unit}})</label><input id="stock-{{p[0]}}" name="quantity" type="number" min="0" step="0.001" required value="{{p[2]|agro_quantity}}"></div><div class="field"><label for="status-{{p[0]}}">Listing status</label><select id="status-{{p[0]}}" name="status">{% for s in ['PENDING','APPROVED','REJECTED','PAUSED','SOLD_OUT'] %}<option value="{{s}}"{% if s==p[5] %} selected{% endif %}>{{s|replace('_',' ')|title}}</option>{% endfor %}</select></div><div class="field"><label for="price-{{p[0]}}">Price (MWK)</label><input id="price-{{p[0]}}" name="price_mwk" type="number" min="0.01" step="0.01" value="{{p[8] or ''}}" required></div><div class="field"><label for="per-{{p[0]}}">Price per</label><input id="per-{{p[0]}}" name="price_unit" maxlength="80" value="{{p[9] or ''}}" required></div><button type="submit">Save changes</button></form><p class="admin-help">Pause to temporarily hide a listing. Saving stock does not reserve or sell any produce.</p></div></div></section>{% else %}<section class="empty"><h3>No produce listings yet</h3><p>Review an agricultural seller request to create a pending listing.</p><a class="button" href="/admin/service-requests">Review service requests</a></section>{% endfor %}</div>
''' + END

VARIANT_FIELDS = r'''<fieldset class="variant-row"><legend>Variety / pack size</legend><div class="form-grid">
<div class="field full"><label>Variety name *</label><input name="variant_name" maxlength="150" required value="{{v.name or ''}}" placeholder="e.g. White rice"></div>
<div class="field"><label>Available quantity *</label><input name="variant_quantity" type="number" min="0.001" max="9999999999999.999" step="0.001" inputmode="decimal" required value="{{v.quantity or ''}}"></div>
<div class="field"><label>Quantity unit *</label><input name="variant_unit" maxlength="80" required value="{{v.unit or ''}}" placeholder="e.g. kg or 50 kg bags"></div>
<div class="field"><label>Price (MWK) *</label><input name="variant_price" type="number" min="0.01" step="0.01" inputmode="decimal" required value="{{v.price or ''}}"></div>
<div class="field"><label>Price per *</label><input name="variant_price_unit" maxlength="80" required value="{{v.price_unit or ''}}" placeholder="e.g. kg or 50 kg bag"></div>
</div><button class="secondary remove-variety" type="button">Remove variety</button></fieldset>'''
VARIANT_SCRIPT = r'''<script>
(function(){
const rows=document.getElementById('variety-rows'), add=document.getElementById('add-variety');
if(!rows||!add)return;
function sync(){const all=rows.querySelectorAll('.variant-row');add.disabled=all.length>=20;all.forEach(row=>{row.querySelector('.remove-variety').hidden=all.length===1;});}
add.addEventListener('click',()=>{if(rows.children.length>=20)return;const row=rows.querySelector('.variant-row').cloneNode(true);row.querySelectorAll('input').forEach(i=>i.value='');rows.appendChild(row);sync();row.querySelector('input').focus();});
rows.addEventListener('click',e=>{if(e.target.classList.contains('remove-variety')&&rows.children.length>1){e.target.closest('.variant-row').remove();sync();}});sync();
})();
</script>'''
IMPORT = START + r'''
<div class="page-heading"><a class="back-link" href="/admin/agro-marketplace">← Back to produce management</a><p class="eyebrow">IBROWS ADMINISTRATION</p><h1>Prepare produce listings</h1><p class="intro">Give each variety its own confirmed stock and price. All listings start pending review.</p></div>
<div class="form-layout"><section class="panel"><h2>Seller request {{ref}}</h2>
<dl class="summary"><div><dt>Produce</dt><dd>{{commodity}}</dd></div><div><dt>Original quantity</dt><dd>{{qty}} {{unit}}</dd></div><div><dt>Variety supplied</dt><dd>{{source_grade or 'Not specified'}}</dd></div><div><dt>Seller's expected price</dt><dd>{{source_price or 'Not specified'}}</dd></div><div class="full"><dt>Location</dt><dd>{{location}}</dd></div></dl>
<p class="notice">Confirm the available quantity for every variety. A combined total must not be repeated as the stock of each variety.</p>
{% if error %}<p class="error" role="alert">{{error}}</p>{% endif %}
<form method="post"><input type="hidden" name="csrf_token" value="{{csrf}}"><div id="variety-rows">{% for v in options %}''' + VARIANT_FIELDS + r'''{% endfor %}</div>
<button type="button" class="secondary" id="add-variety">+ Add another variety</button>
<label class="check"><input type="checkbox" name="confirm" value="yes" required><span>I have verified stock and price separately for every variety.</span></label>
<label class="check"><input type="checkbox" name="seller_consent" value="yes" required><span>The seller has authorized IBROWS to advertise this produce.</span></label>
<div class="form-actions"><button>Create pending listings</button></div></form></section>
<aside class="panel side-panel"><h2>Review before publishing</h2><div><h3>Separate prices</h3><p>For example, white rice and brown rice appear as separate product cards with their own quantities and prices.</p></div><div><h3>Approval required</h3><p>Use produce management to approve each listing. Seller contacts remain private and all enquiries go through IBROWS.</p></div></aside></div>
''' + VARIANT_SCRIPT + END
